import {buildVisibleOpticalInstances} from './visible-optics.js';
import {GroundMotion,GroundGait} from './grounded-motion.js';
import {initialState,cellId,CELL_IDS,localPoint,canonicalFrame,worldToTangent,dot,H} from './chapter-topology.js';
import {ChapterProgress} from './chapter-progress.js';
import {integrateThrust,advanceWithCollision,upperEyeZ,viewBasis} from './chapter-motion.js';
import {LookController} from './look.js';
import {StationRenderer} from './station-renderer.js';
import {createHypothesisLab} from './hypotheses.js';
import {ROOM_MODELS,roomModel} from './model-content.js';
const B=window.BABYLON,$=id=>document.getElementById(id),canvas=$('world'),look=new LookController();
let engine,scene,camera,renderer,lab,ready=false,locked=false,labRoom=null,state=initialState(),progress=new ChapterProgress(),velocity=[0,0,0],keys=new Set(),time=0,sensitivity=1,gesture={left:-10,right:-10},ground=new GroundMotion(),gait=new GroundGait(),locomotion={leftLeg:0,rightLeg:0,crouchScale:1},jumpQueued=false,zoom=false,lastSeamMS=0,seamCount=0,lockTime=0,lastHUD=-1,autoplay=true,labTravel=0,debug=false;
state.p[2]=upperEyeZ(false);state.p[0]=-2.3;
function phase(){return progress.phase==='upper'?'upper':'lower';}
function id(){return cellId(state.normal);}
function updateHUD(){let p=progress.snapshot(),upper=p.phase==='upper';$('cell').textContent=id();$('phaseTitle').textContent=`第一章 · ${upper?'上半部 / 玻璃回廊':p.phase==='ended'?'边界之外':'下半部 / 六向漂航'}${debug||p.debugUsed?' · 测试模式':''}`;$('anchor').textContent=state.frame.map((v,i)=>`${['右','上','前'][i]} ${cellId(v)}`).join('  ');$('objective').textContent=upper?`走完四胞回环 ${p.loopComplete?'✓':p.loopSteps+'/4'}，观察三个空间假说；回 W+ 控制台自主解除限制。`:p.routeComplete?'不重复八胞路线已完成。W+ 已出现镜面球，返回并进入即可完成第一章。':p.routeActive?'路线挑战进行中：连续进入八个不同房间。':p.routeFailure?`路线在 ${p.routeFailure.cell} 重复，已停止；模型记录保留。请回 W+ 控制台重新开始。`:p.surveyComplete?'尝试从 W＋开始，不重复地走过八个不同房间吧':'先熟悉六向通道：下半部每个房间各进入 3 遍，再触发不重复路线挑战。';$('route').textContent=upper?'W+ → X+ → W− → X− → W+':`${p.routeComplete?'路线完成 ✓':p.routeActive?'本次路线':'路线待启动'} ${p.routeTrail.length}/8\n${p.routeTrail.join(' → ')}`;$('modelsProgress').textContent=(upper?'':`熟悉空间：${Object.entries(p.counts).map(([c,n])=>c+' '+Math.min(n,3)+'/3').join('  ')}\n`)+`模型已操作 ${p.inspected.length}/3\n`+['W+','X+','W-'].map(c=>roomModel(c).title+(p.inspected.includes(c)?' ✓':' ·')).join('  ');$('hint').textContent=upper?'WASD 行走 · Space 跳跃 · F 望远镜 · E 模型 · 左/右键挥手':'W/S 视线喷气 · A/D 侧喷 · Space/Ctrl 身体上下 · F 望远镜 · E 模型';if(labRoom)refreshLabStatus();}
function refreshLabStatus(){let snap=progress.snapshot();$('inspectionStatus').textContent=progress.hasModel(labRoom)?'已亲手操纵此模型，观察记录已保存。':'拖动下方「实验行程」；仅观看自动演示不会记录为已操作。';$('unlock').classList.toggle('hidden',progress.phase!=='upper');$('unlock').disabled=!(progress.canUnlock&&id()==='W+');$('unlockHint').textContent=progress.phase==='upper'?`解锁条件：四胞回环 ${progress.loopComplete?'✓':'未完成'}；三个空间假说 ${['W+','X+','W-'].filter(c=>progress.hasModel(c)).length}/3；需身处 W+。`:'';$('beginRoute').classList.toggle('hidden',progress.phase!=='lower'||progress.routeComplete);$('beginRoute').disabled=progress.routeActive||!progress.surveyComplete||id()!=='W+';$('beginRoute').textContent=progress.routeActive?'路线正在进行':progress.routeFailure?'从 W+ 重新开始路线':'从 W+ 开始不重复八胞路线';$('routeHelp').textContent=progress.phase==='lower'?'每房进入 3 遍后，从 W+ 开始挑战。进入房间内部才确认经过；重复会终止本次路线，需回 W+ 重启，但熟悉次数与模型记录保留。第八个不同房间确认后成功，W+ 立即出现镜面球。模型阅读不再阻拦最终出口。':'';}
function setZoom(value){zoom=!!value;if(camera)camera.fov=zoom?.28:1.16;$('binocular').classList.toggle('hidden',!zoom);}
function pause(show=true){keys.clear();jumpQueued=false;setZoom(false);look.transition();document.exitPointerLock?.();if(show&&!labRoom&&progress.phase!=='ended')$('menu').classList.remove('hidden');}
function closeLab(){if(!labRoom)return;labRoom=null;lab?.dispose();lab=null;$('console').classList.add('hidden');$('menu').classList.remove('hidden');$('start').textContent='继续巡查';}
function openLab(room=id()){if(!ROOM_MODELS[room])room='W+';if(!ready||progress.phase==='ended')return;pause(false);labRoom=room;autoplay=true;labTravel=0;$('modelPlay').textContent='暂停演示';$('menu').classList.add('hidden');$('console').classList.remove('hidden');const c=roomModel(room);$('modelRoom').textContent=`${room} / HOLOGRAPHIC EXPERIMENT`;$('modelTitle').textContent=c.title;$('modelExplanation').textContent=c.explanation;$('modelPrediction').textContent=c.prediction;$('modelExperiment').textContent=c.experiment;$('travel').value='0';$('travelValue').textContent='0.00';if(!lab)lab=createHypothesisLab(B,$('labCanvas'),cell=>{progress.inspectModel(cell);updateHUD();});lab.selectRoom(room);lab.setAnimationTravel(0);lab.resize();$('modelIndex').replaceChildren();for(let cell of ['W+','X+','W-']){let button=document.createElement('button');button.textContent=roomModel(cell).title+(progress.hasModel(cell)?' ✓':'');button.disabled=false;button.onclick=()=>openLab(cell);$('modelIndex').appendChild(button);}refreshLabStatus();}
function reset(){pause(false);lab?.dispose();lab=null;labRoom=null;state=initialState();state.p[2]=upperEyeZ(false);state.p[0]=-2.3;progress=new ChapterProgress();velocity=[0,0,0];ground.reset();gait.reset();jumpQueued=false;setZoom(false);look.reset();gesture={left:-10,right:-10};debug=false;$('console').classList.add('hidden');$('ending').classList.add('hidden');$('menu').classList.remove('hidden');renderer.rebuild(state,'upper');updateHUD();}
async function lower(){if(!progress.unlockLower(id(),time))return;velocity=[0,0,0];closeLab();ready=false;$('start').disabled=true;$('notice').textContent='正在准备零重力舱段与渲染资源…准备好后点击继续。';updateHUD();await new Promise(resolve=>requestAnimationFrame(()=>setTimeout(resolve,0)));renderer.rebuild(state,'lower');scene.executeWhenReady(()=>{ready=true;$('start').disabled=false;$('notice').textContent='六面通道已打开，重力关闭。喷气松开后惯性漂移，宇航服辅助制动缓慢减速。';});}

function finish(){if(!progress.enterBubble(id()))return;pause(false);velocity=[0,0,0];$('menu').classList.add('hidden');$('ending').classList.remove('hidden');updateHUD();}
try{
 engine=new B.Engine(canvas,true,{stencil:true,preserveDrawingBuffer:true});engine.setHardwareScalingLevel(Math.max(1,(window.devicePixelRatio||1)/1.25));scene=new B.Scene(engine);scene.clearColor=new B.Color4(.58,.64,.66,1);camera=new B.UniversalCamera('astronaut eyes',new B.Vector3(...localPoint(state)),scene);camera.inputs.clear();camera.fov=1.16;camera.minZ=.045;camera.maxZ=55;renderer=new StationRenderer(B,scene);renderer.rebuild(state,'upper');
 scene.executeWhenReady(()=>{ready=true;$('start').disabled=false;$('start').textContent='开始巡查';});
 engine.runRenderLoop(()=>{let dt=Math.min(engine.getDeltaTime()/1000,.05);time+=dt;let changed=false;
 if(locked&&ready&&progress.phase!=='ended'){
  let pose=look.frame();camera.rotation.set(pose.pitch,pose.yaw,0);const up=phase()==='upper';
  let beforeP=[...state.p];let strafe=Number(keys.has('KeyD'))-Number(keys.has('KeyA')),forward=Number(keys.has('KeyW'))-Number(keys.has('KeyS')),rise=Number(keys.has('Space'))-Number(keys.has('ControlLeft')||keys.has('ControlRight')||keys.has('KeyQ')),displacement;
  if(up){let len=Math.hypot(strafe,forward)||1;strafe/=len;forward/=len;let speed=keys.has('KeyC')?1.5:2.7;let fall=ground.step(dt,jumpQueued,keys.has('KeyC'));jumpQueued=false;velocity=[(Math.cos(look.yaw)*strafe+Math.sin(look.yaw)*forward)*speed,fall.verticalVelocity,(-Math.sin(look.yaw)*strafe+Math.cos(look.yaw)*forward)*speed];displacement=[velocity[0]*dt,fall.eyeZ-state.p[2],velocity[2]*dt];}
  else{let integrated=integrateThrust(velocity,[strafe,rise,forward],look.yaw,look.pitch,dt);velocity=integrated.velocity;displacement=integrated.displacement;}
  let moved=advanceWithCollision(state,velocity,displacement,up?'upper':'lower');state=moved.state;velocity=moved.velocity;if(up&&Math.abs(state.p[2]-ground.eyeZ)>1e-7){ground.eyeZ=state.p[2];ground.footLift=Math.max(0,ground.eyeZ+4-1.68);ground.verticalVelocity=velocity[1];ground.airborne=ground.footLift>1e-8||ground.verticalVelocity>0;}let actualDistance=Math.hypot(...state.p.map((v,i)=>i===2?0:v-beforeP[i]));locomotion={...gait.step(actualDistance,dt,actualDistance/Math.max(dt,.001),up&&ground.airborne,!up),crouchScale:up&&keys.has('KeyC')&&!ground.airborne?1.15/1.68:1};
  for(let seam of moved.crossings){progress.onCross(cellId(seam.to),time);changed=true;}
  if(changed){let cpuStart=performance.now();renderer.rebuild(state,phase());lastSeamMS=performance.now()-cpuStart;seamCount+=moved.crossings.length;}
  let q=localPoint(state),depth=Math.min(...q.map(v=>H-Math.abs(v)));if(progress.updateInterior(id(),depth,time))changed=true;
  if(progress.bubbleVisible(id())){let cf=canonicalFrame(state.normal),p=worldToTangent(cf,state.p);if(Math.hypot(p[0]-1.55,p[1]+.1,p[2])<1.15)finish();}
 }
 camera.position.set(...localPoint(state));const visible=buildVisibleOpticalInstances(state,phase(),look,{fov:camera.fov,aspect:engine.getRenderWidth()/engine.getRenderHeight()}),signature=phase()+visible.map(x=>x.path.join('/')).join('|');if(signature!==renderer.visibleSignature)renderer.rebuild(state,phase(),visible);renderer.update(state,look,phase(),time,gesture,progress.routeComplete&&progress.phase==='lower',{...locomotion,hideLocal:zoom});
 if(lab&&autoplay){labTravel=(labTravel+dt*.24)%4;let travel=labTravel;lab.setAnimationTravel(travel);$('travel').value=String(travel);$('travelValue').textContent=travel.toFixed(2);}
 scene.render();if(changed||time-lastHUD>.2){lastHUD=time;updateHUD();$('stats').textContent=`${Math.round(engine.getFps())} FPS · ${locked?(zoom?'望远镜':'鼠标锁定'):'暂停'} · 8 胞 / 光路预算 4`;$('perfdiag').textContent=`本机渲染 ${Math.round(engine.getFps())} FPS / ${engine.getDeltaTime().toFixed(1)}ms；最近跨缝 CPU ${lastSeamMS.toFixed(2)}ms（${seamCount} 次）；常驻网格 ${scene.meshes.length} / 材质 ${scene.materials.length}。仅本机诊断，不上传；CPU 时间不等于 GPU 总帧耗时。`;$('lookdiag').textContent=`视角输入：最大包 ${Math.round(look.maxPacket)} px；异常包 ${look.filtered}；速度 ${Math.hypot(...velocity).toFixed(1)} m/s`;}
 });
}catch(e){$('notice').textContent='无法启动实时 3D：'+e.message;$('start').textContent='此浏览器需要可用的 WebGL';console.error(e);}
$('start').onclick=async()=>{if(!ready)return;$('notice').textContent='';try{canvas.focus();try{await canvas.requestPointerLock({unadjustedMovement:true});}catch(e){if(e.name==='NotSupportedError')await canvas.requestPointerLock();else throw e;}}catch(e){$('notice').textContent='鼠标锁定未成功，请再次点击；检查浏览器对此页面的鼠标锁定权限。';}};
document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===canvas;keys.clear();jumpQueued=false;look.transition();if(!locked)setZoom(false);lockTime=time;$('menu').classList.toggle('hidden',locked||!!labRoom||progress.phase==='ended');$('start').textContent='继续巡查';});document.addEventListener('pointerlockerror',()=>{$('notice').textContent='未获得鼠标锁定，请再次点击。';});document.addEventListener('mousemove',e=>{if(locked)look.push(e.movementX,e.movementY,sensitivity*(zoom?Math.tan(.28/2)/Math.tan(1.16/2):1));});
document.addEventListener('mousedown',e=>{if(!locked||time-lockTime<.2)return;if(e.button===0)gesture.left=time;if(e.button===2)gesture.right=time;});canvas.addEventListener('contextmenu',e=>{if(locked)e.preventDefault();});
document.addEventListener('keydown',e=>{if(e.code==='Escape'&&labRoom){closeLab();return;}if(!locked)return;if(e.code==='KeyF'&&!e.repeat&&!['INPUT','TEXTAREA','SELECT'].includes(e.target?.tagName)){e.preventDefault();setZoom(!zoom);return;}if(e.code==='Space'&&phase()==='upper'&&!e.repeat&&!keys.has('Space'))jumpQueued=true;if(['KeyW','KeyA','KeyS','KeyD','Space','ControlLeft','ControlRight','KeyQ','KeyC'].includes(e.code)){e.preventDefault();keys.add(e.code);}if(e.code==='KeyE'&&!e.repeat&&Math.hypot(...localPoint(state))<4.8){e.preventDefault();openLab();}});document.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>pause());document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});$('pause').onclick=()=>pause();$('closeLab').onclick=closeLab;$('travel').oninput=e=>{autoplay=false;$('modelPlay').textContent='继续演示';labTravel=+e.target.value;lab?.setTravel(labTravel);$('travelValue').textContent=(+e.target.value).toFixed(2);};$('unlock').onclick=lower;$('beginRoute').onclick=()=>{if(progress.startRoute(id(),time)){refreshLabStatus();updateHUD();}};$('sensitivity').oninput=e=>{sensitivity=+e.target.value;$('sensvalue').textContent=sensitivity.toFixed(1)+'×';};$('reset').onclick=()=>{if(ready)reset();};
$('debugLower').onclick=()=>{if(!ready)return;debug=true;ground.reset();gait.reset();state=initialState();state.p[2]=upperEyeZ(false);progress.currentCell='W+';progress.loopComplete=true;for(let c of ['W+','X+','W-','X-'])progress.inspectModel(c);progress.unlockLower('W+',time);velocity=[0,0,0];look.reset();renderer.rebuild(state,'lower');updateHUD();$('notice').textContent='测试模式：已跳至下半部。';};$('debugEnd').onclick=()=>{if(!ready)return;if(progress.phase==='upper')$('debugLower').onclick();debug=true;progress.debugCompleteRoute();progress.debugInspectAll();state=initialState();state.p[0]=-2.6;progress.currentCell='W+';velocity=[0,0,0];look.reset();renderer.rebuild(state,'lower');updateHUD();$('notice').textContent='测试模式：W+ 镜面球已出现。';};$('returnExplore').onclick=()=>{progress.phase='lower';progress.completed=false;state=initialState();state.p[0]=-2.6;progress.currentCell='W+';velocity=[0,0,0];look.reset();renderer.rebuild(state,'lower');$('ending').classList.add('hidden');$('menu').classList.remove('hidden');updateHUD();};window.addEventListener('resize',()=>{engine?.resize();lab?.resize();});updateHUD();

$('modelPlay').onclick=()=>{if(!lab)return;autoplay=!autoplay;$('modelPlay').textContent=autoplay?'暂停演示':'继续演示';};$('modelReset').onclick=()=>{if(!lab)return;labTravel=0;autoplay=false;lab.setAnimationTravel(0);$('travel').value='0';$('travelValue').textContent='0.00';$('modelPlay').textContent='继续演示';};
